package fetchall

import (
	"context"
	"errors"
	"sync"
)

// Result holds a single successful operation output paired with its input index.
type Result struct {
	Index  int
	Output string
}

// Process runs operation concurrently for each input, limiting concurrency
// to at most concurrency in-flight operations at any moment.
//
// Results are ordered by Index ascending and contain an entry for every input
// that succeeded. When one or more operations fail, Process returns the
// successful results together with a single aggregated error; every individual
// failure remains reachable via errors.Is / errors.As.
//
// concurrency must be >= 1. Empty inputs returns (nil, nil).
func Process(
	ctx context.Context,
	inputs []string,
	concurrency int,
	operation func(ctx context.Context, input string) (string, error),
) ([]Result, error) {
	if concurrency < 1 {
		return nil, errors.New("fetchall: concurrency must be at least 1")
	}
	if len(inputs) == 0 {
		return nil, nil
	}

	type item struct {
		index int
		input string
	}

	var (
		mu      sync.Mutex
		results []Result
		errs    []error
		wg      sync.WaitGroup
		sem     = make(chan struct{}, concurrency)
	)

	for i, input := range inputs {
		it := item{index: i, input: input}

		// Acquire semaphore slot (blocking). Context cancellation while
		// waiting is handled by the per-operation ctx in the goroutine.
		sem <- struct{}{}

		wg.Go(func() {
			defer func() { <-sem }() // release slot

			out, err := operation(ctx, it.input)
			mu.Lock()
			if err != nil {
				errs = append(errs, err)
			} else {
				results = append(results, Result{Index: it.index, Output: out})
			}
			mu.Unlock()
		})
	}

	wg.Wait()

	if len(errs) > 0 {
		return results, errors.Join(errs...)
	}
	return results, nil
}

package fetchall

import (
	"context"
	"errors"
	"fmt"
	"sync"
	"sync/atomic"
	"testing"
	"time"
)

// errSentinel is a sentinel error used to verify errors.Is propagation.
var errSentinel = errors.New("boom")

type errTyped struct{ msg string }

func (e *errTyped) Error() string { return e.msg }

func TestProcess_InvalidConcurrency(t *testing.T) {
	_, err := Process(context.Background(), []string{"a"}, 0, nopOp)
	if err == nil {
		t.Fatal("expected error for concurrency=0")
	}
	_, err = Process(context.Background(), []string{"a"}, -1, nopOp)
	if err == nil {
		t.Fatal("expected error for concurrency=-1")
	}
}

func TestProcess_EmptyInputs(t *testing.T) {
	res, err := Process(context.Background(), nil, 1, nopOp)
	if res != nil || err != nil {
		t.Fatalf("expected (nil, nil), got (%v, %v)", res, err)
	}
	res, err = Process(context.Background(), []string{}, 1, nopOp)
	if res != nil || err != nil {
		t.Fatalf("expected (nil, nil), got (%v, %v)", res, err)
	}
}

func TestProcess_AllSucceed(t *testing.T) {
	inputs := []string{"a", "b", "c"}
	res, err := Process(context.Background(), inputs, 2, echoOp)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if len(res) != len(inputs) {
		t.Fatalf("got %d results, want %d", len(res), len(inputs))
	}
	for i, r := range res {
		if r.Index != i {
			t.Errorf("result %d: Index=%d, want %d", i, r.Index, i)
		}
		if r.Output != inputs[i] {
			t.Errorf("result %d: Output=%q, want %q", i, r.Output, inputs[i])
		}
	}
}

func TestProcess_ResultsOrdered(t *testing.T) {
	// Operations sleep proportional to index so later inputs finish first;
	// the output must still be ordered by index.
	inputs := []string{"0", "1", "2", "3", "4"}
	op := func(ctx context.Context, input string) (string, error) {
		time.Sleep(time.Duration(5-'0'+input[0]) * time.Millisecond)
		return "x" + input, nil
	}
	res, err := Process(context.Background(), inputs, 5, op)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if len(res) != len(inputs) {
		t.Fatalf("got %d results, want %d", len(res), len(inputs))
	}
	for i, r := range res {
		if r.Index != i {
			t.Errorf("result %d: Index=%d, want %d", i, r.Index, i)
		}
	}
}

func TestProcess_SomeFail(t *testing.T) {
	inputs := []string{"ok", "fail", "ok2", "fail2"}
	op := func(ctx context.Context, input string) (string, error) {
		if input == "fail" || input == "fail2" {
			return "", fmt.Errorf("op %q: %w", input, errSentinel)
		}
		return input, nil
	}
	res, err := Process(context.Background(), inputs, 2, op)
	if err == nil {
		t.Fatal("expected aggregated error")
	}
	if len(res) != 2 {
		t.Fatalf("got %d successful results, want 2", len(res))
	}
	// Verify ordering.
	if res[0].Index != 0 || res[0].Output != "ok" {
		t.Errorf("first result mismatch: %+v", res[0])
	}
	if res[1].Index != 2 || res[1].Output != "ok2" {
		t.Errorf("second result mismatch: %+v", res[1])
	}
	// Every individual failure must be reachable.
	if !errors.Is(err, errSentinel) {
		t.Error("aggregated error does not wrap errSentinel")
	}
}

func TestProcess_AllFail(t *testing.T) {
	inputs := []string{"a", "b", "c"}
	op := func(ctx context.Context, input string) (string, error) {
		return "", &errTyped{msg: "fail: " + input}
	}
	res, err := Process(context.Background(), inputs, 2, op)
	if err == nil {
		t.Fatal("expected aggregated error")
	}
	if len(res) != 0 {
		t.Fatalf("expected 0 successful results, got %d", len(res))
	}
	// Verify typed error reachable via errors.As.
	var typed *errTyped
	if !errors.As(err, &typed) {
		t.Error("aggregated error should contain *errTyped")
	}
}

func TestProcess_ConcurrencyBoundRespected(t *testing.T) {
	const (
		n            = 20
		concurrency  = 3
	)

	var (
		mu         sync.Mutex
		peak       int
		inflight   int32
		started    = make(chan struct{}, n)
		allowProceed = make(chan struct{})
	)

	op := func(ctx context.Context, input string) (string, error) {
		started <- struct{}{}
		v := int(atomic.AddInt32(&inflight, 1))
		mu.Lock()
		if v > peak {
			peak = v
		}
		mu.Unlock()
		<-allowProceed
		atomic.AddInt32(&inflight, -1)
		return input, nil
	}

	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()

	go func() {
		// Wait for all goroutines to be started (blocked on allowProceed).
		for i := 0; i < n; i++ {
			<-started
		}
		close(allowProceed)
	}()

	res, err := Process(ctx, makeInputs(n), concurrency, op)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if len(res) != n {
		t.Fatalf("got %d results, want %d", len(res), n)
	}
	if peak > concurrency {
		t.Fatalf("peak concurrency %d exceeds limit %d", peak, concurrency)
	}
}

func TestProcess_ContextCancellation(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	cancel() // already cancelled

	res, err := Process(ctx, []string{"a", "b"}, 2, func(ctx context.Context, input string) (string, error) {
		select {
		case <-ctx.Done():
			return "", ctx.Err()
		default:
			return input, nil
		}
	})

	if err == nil {
		t.Fatal("expected error from cancelled context")
	}
	if !errors.Is(err, context.Canceled) {
		t.Errorf("expected context.Canceled, got %v", err)
	}
	if len(res) != 0 {
		t.Errorf("expected 0 results, got %d", len(res))
	}
}

func TestProcess_ConcurrencyOne(t *testing.T) {
	// Sequential execution: one at a time.
	var orderMu sync.Mutex
	var order []int

	op := func(ctx context.Context, input string) (string, error) {
		time.Sleep(5 * time.Millisecond)
		orderMu.Lock()
		order = append(order, int(input[0]-'0'))
		orderMu.Unlock()
		return input, nil
	}

	res, err := Process(context.Background(), []string{"0", "1", "2"}, 1, op)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if len(res) != 3 {
		t.Fatalf("got %d results, want 3", len(res))
	}
	// With concurrency=1 the order slice should be [0,1,2] because operations
	// run sequentially (no reordering even though sleep is uniform).
	if len(order) != 3 || order[0] != 0 || order[1] != 1 || order[2] != 2 {
		t.Errorf("unexpected execution order: %v", order)
	}
}

// --- helpers ---

func nopOp(_ context.Context, input string) (string, error) {
	return input, nil
}

func echoOp(_ context.Context, input string) (string, error) {
	return input, nil
}

func makeInputs(n int) []string {
	s := make([]string, n)
	for i := range s {
		s[i] = fmt.Sprintf("%d", i)
	}
	return s
}

